(function (window) {
    var hljs = {
        highlight: function (code, opts) {
            var lang = (opts && opts.language) ? opts.language.toLowerCase() : 'text';
            var html = hljs.escape(code);
            return { value: hljs.colorize(html, lang) };
        },
        highlightAuto: function (code) {
            var lang = hljs.detectLanguage(code);
            return hljs.highlight(code, { language: lang });
        },
        getLanguage: function (lang) {
            return true;
        },
        escape: function (str) {
            return str
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        },
        detectLanguage: function (code) {
            if (/^\s*(\/\/|#|\/\*)\s*.*?\.(ts|js|rs|py|go|cpp|c|json|html|css|sh|sql)/i.test(code)) {
                var m = code.match(/\.([a-z0-9]+)/i);
                if (m) return m[1];
            }
            if (/import\s+.*?from|export\s+interface|class\s+\w+|const\s+\w+\s*:/i.test(code)) return 'typescript';
            if (/def\s+\w+\(|import\s+os|self\.|print\(/i.test(code)) return 'python';
            if (/fn\s+\w+\(|pub\s+struct|let\s+mut|impl\s+/i.test(code)) return 'rust';
            if (/package\s+main|func\s+\w+\(|go\s+func/i.test(code)) return 'go';
            if (/^\s*SELECT\s+.*?\s+FROM|INSERT\s+INTO|CREATE\s+TABLE/i.test(code)) return 'sql';
            if (/^\s*<[!a-zA-Z]/i.test(code)) return 'html';
            if (/^\s*\{[\s\S]*\}\s*$/i.test(code)) return 'json';
            return 'javascript';
        },
        colorize: function (escapedCode, lang) {
            return escapedCode
                // Comments
                .replace(/(\/\/[^\n]*|#[^\n]*|\/\*[\s\S]*?\*\/)/g, '<span class="hljs-comment" style="color:#6a9955;font-style:italic;">$1</span>')
                // Keywords
                .replace(/\b(import|export|from|const|let|var|function|class|interface|type|public|private|protected|async|await|return|if|else|for|while|try|catch|finally|struct|impl|fn|pub|def|self|select|from|where|insert|into|update|delete|as)\b/g, '<span class="hljs-keyword" style="color:#569cd6;font-weight:bold;">$1</span>')
                // Strings
                .replace(/(&quot;[\s\S]*?&quot;|&#39;[\s\S]*?&#39;|`[\s\S]*?`)/g, '<span class="hljs-string" style="color:#ce9178;">$1</span>')
                // Numbers
                .replace(/\b(\d+(\.\d+)?)\b/g, '<span class="hljs-number" style="color:#b5cea8;">$1</span>')
                // Types / Classes
                .replace(/\b([A-Z][a-zA-Z0-9_]*)\b/g, '<span class="hljs-title" style="color:#4ec9b0;">$1</span>');
        }
    };
    window.hljs = hljs;
})(window);
